var data = msg.payload;
if (typeof data === "string") {
    data = JSON.parse(data);
}

// Ghi nhan NodeMCU con song (heartbeat qua telemetry data/sensor)
global.set("nodemcu_last_seen", Date.now());
global.set("nodemcu_online", true);

var now = new Date();
var q = "INSERT INTO data_sensors (sensor_id, value, recorded_at) VALUES (?, ?, ?)";

var msgs = [
    { topic: q, payload: [1, data.temp, now] },
    { topic: q, payload: [2, data.hum, now] },
    { topic: q, payload: [3, data.light, now] }
];

return [msgs];

var device = msg.topic.indexOf("led1") !== -1 ? "led1" : "led2";
var actionText = device + ":" + msg.payload;
var deviceId = (device === "led1") ? 1 : 2;

var key = "ui_cmd_" + device;
var list = (global.get(key) || []).filter(function (item) {
    var t = (typeof item === "object") ? item.time : item;
    return Date.now() - t < 5000;
});
var fromUI = list.length > 0;
var userId = null;
if (fromUI) {
    var cmd = list.shift();
    userId = (typeof cmd === "object" && cmd.user_id) ? cmd.user_id : 1;
}
global.set(key, list);

msg.topic = "INSERT INTO actions (device_id, user_id, action, status, time) VALUES (?, ?, ?, 'pending', NOW(3))";
msg.payload = [deviceId, userId, actionText];
msg._device = device;
return msg;

var insertId = msg.payload.insertId;
var device = msg._device;

// Ghi nho lenh dang cho phan hoi cua tung den
flow.set("pending_" + device, insertId);

setTimeout(function () {
    // Luon thu danh dau timeout sau 5s. Dieu kien status='pending' trong SQL dam bao
    // khong ghi de ban ghi da duoc cap nhat success/failed; ban ghi bi lenh moi ghi de
    // (bam cong tac lien tuc) cung se khong bi ket o 'pending'.
    node.send({
        topic: "UPDATE actions SET status='timeout' WHERE action_id=? AND status='pending'",
        payload: [insertId]
    });
    node.done();
    if (flow.get("pending_" + device) === insertId) {
        flow.set("pending_" + device, null);
    }
}, 5000);

return null;

var data = msg.payload;
if (typeof data === "string") {
    try { data = JSON.parse(data); } catch(e) {}
}

if (!data || !data.device) {
    return null;
}

// Bat tin nhan LWT va ket noi cua NodeMCU
if (data.device === "node") {
    if (data.state === "ONLINE") {
        global.set("nodemcu_online", true);
        global.set("nodemcu_last_seen", Date.now());
    } else if (data.state === "OFFLINE") {
        global.set("nodemcu_online", false);
    }
    return null;
}

var actionId = flow.get("pending_" + data.device);
if (!actionId) {
    return null;
}

flow.set("pending_" + data.device, null);

var dbStatus = (data.status === "success") ? "success" : "failed";

msg.topic = "UPDATE actions SET status=?, time_response=NOW(3) WHERE action_id=?";
msg.payload = [dbStatus, actionId];
return msg;

msg.topic = "SELECT sensor_id, value, recorded_at FROM data_sensors ORDER BY recorded_at DESC LIMIT 30";
msg.payload = [];
return msg;

var rows = msg.payload;
var bySensor = {1: [], 2: [], 3: []};
rows.forEach(function (r) { if (bySensor[r.sensor_id]) bySensor[r.sensor_id].push(r); });

var chart = {};
var latest = {};
[1, 2, 3].forEach(function (sid) {
    var arr = bySensor[sid].slice(0, 10).reverse();
    chart[sid] = arr.map(function (r) { return { t: r.recorded_at, v: parseFloat(r.value) }; });
    latest[sid] = arr.length ? parseFloat(arr[arr.length - 1].value) : null;
});

msg._latest = latest;
msg._chart = chart;
msg.topic = "SELECT action, time FROM actions WHERE status=\'success\' AND (action LIKE \'led1:%\' OR action LIKE \'led2:%\') ORDER BY time DESC LIMIT 20";
msg.payload = [];
return msg;

var rows = msg.payload;
var led1 = "OFF", led2 = "OFF", found1 = false, found2 = false;

for (var i = 0; i < rows.length; i++) {
    var a = rows[i].action;
    if (!found1 && a.indexOf("led1:") === 0) { led1 = a.split(":")[1]; found1 = true; }
    if (!found2 && a.indexOf("led2:") === 0) { led2 = a.split(":")[1]; found2 = true; }
    if (found1 && found2) break;
}

var threshold = global.get("light_threshold") || 800;
var isAlert = global.get("light_alert_active") || false;
var curLight = msg._latest[3];
if (curLight != null && curLight >= threshold) {
    isAlert = true;
}

var lastSeen = global.get("nodemcu_last_seen") || 0;
var nodeOnline = global.get("nodemcu_online");
// NodeMCU phat telemetry 5s/lan. Neu qua 9s khong co ban ghi -> Offline ngay lap tuc!
var isNodeOnline = (nodeOnline !== false) && (lastSeen > 0) && (Date.now() - lastSeen < 9000);
if (nodeOnline === false || (lastSeen > 0 && Date.now() - lastSeen >= 9000)) {
    isNodeOnline = false;
}

msg.payload = {
    temp: msg._latest[1], hum: msg._latest[2], light: msg._latest[3],
    led1: led1, led2: led2, chart: msg._chart,
    light_threshold: threshold,
    is_light_alert: isAlert,
    nodemcu_online: isNodeOnline,
    nodemcu_last_seen: lastSeen
};
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization"
};
return msg;

// Nhan hien thi cua loai cam bien (tieng Viet)
var TYPE_LABEL = "CASE s.sensor_type WHEN 'temperature' THEN 'Nhiệt độ' WHEN 'humidity' THEN 'Độ ẩm' WHEN 'light' THEN 'Ánh sáng' ELSE s.sensor_type END";

var q = msg.req.query || {};
var search = (q.search || "").trim();
var field = (q.field || "all").trim();   // all | id | name | type | value | unit | time
var type = (q.type || "").trim();        // (tuy chon) loc cung theo loai: temperature | humidity | light
var page = Math.max(parseInt(q.page) || 1, 1);
var pageSize = Math.min(Math.max(parseInt(q.pageSize) || 10, 1), 100);   // toi da 100 dong/trang
var offset = (page - 1) * pageSize;

var where = [];
var params = [];
if (type) { where.push("s.sensor_type = ?"); params.push(type); }

if (search) {
    var like = "%" + search.replace(/[\\%_]/g, "\\$&") + "%";   // escape % _ \ de tim dung ky tu nguoi dung go
    // Moi cot co the tim: [dieu kien SQL, so dau ? trong dieu kien]
    var cols = {
        id:    ["CAST(d.data_id AS CHAR) LIKE ?", 1],
        name:  ["s.sensor_name LIKE ?", 1],
        type:  ["(s.sensor_type LIKE ? OR " + TYPE_LABEL + " LIKE ?)", 2],
        value: ["CAST(d.value AS CHAR) LIKE ?", 1],
        unit:  ["s.unit LIKE ?", 1],
        time:  ["DATE_FORMAT(d.recorded_at, '%Y-%m-%d %H:%i:%s') LIKE ?", 1]
    };
    var keys = cols[field] ? [field] : Object.keys(cols);   // "Tat ca": khop o bat ky cot nao
    var parts = keys.map(function (k) {
        for (var i = 0; i < cols[k][1]; i++) params.push(like);
        return cols[k][0];
    });
    where.push(parts.length > 1 ? "(" + parts.join(" OR ") + ")" : parts[0]);
}
var whereSQL = where.length ? ("WHERE " + where.join(" AND ")) : "";

msg._page = page; msg._pageSize = pageSize; msg._where = whereSQL; msg._params = params;

msg.topic = "SELECT d.data_id, s.sensor_name, s.sensor_type, " + TYPE_LABEL + " AS sensor_type_label, s.unit, d.value, d.recorded_at " +
            "FROM data_sensors d JOIN sensors s ON s.sensor_id = d.sensor_id " + whereSQL +
            " ORDER BY d.recorded_at DESC, d.data_id DESC LIMIT ? OFFSET ?";
msg.payload = params.concat([pageSize, offset]);
return msg;

msg._rows = msg.payload;
msg.topic = "SELECT COUNT(*) AS total FROM data_sensors d JOIN sensors s ON s.sensor_id = d.sensor_id " + msg._where;
msg.payload = msg._params;
return msg;

msg.payload = {
    rows: msg._rows,
    total: msg.payload[0].total,
    page: msg._page,
    pageSize: msg._pageSize
};
msg.headers = { "Access-Control-Allow-Origin": "*" };
return msg;

var q = msg.req.query || {};
var device = (q.device || "").trim();
var status = (q.status || "").trim();
var action = (q.action || "").trim().toUpperCase();  // ON | OFF
var time = (q.time || "").trim();                    // vd: 2026-10-09 hoac 2026-10-09 14:30
var page = Math.max(parseInt(q.page) || 1, 1);
var pageSize = Math.min(Math.max(parseInt(q.pageSize) || 10, 1), 100);   // toi da 100 dong/trang
var offset = (page - 1) * pageSize;

var where = [];
var params = [];
if (device) { where.push("a.device_id = ?"); params.push(device); }
if (status) { where.push("a.status = ?"); params.push(status); }
if (action === "ON" || action === "OFF") { where.push("a.action LIKE ?"); params.push("%:" + action); }
if (time) { where.push("DATE_FORMAT(a.time, '%Y-%m-%d %H:%i:%s') LIKE ?"); params.push("%" + time.replace(/[\\%_]/g, "\\$&") + "%"); }
var whereSQL = where.length ? ("WHERE " + where.join(" AND ")) : "";

msg._page = page; msg._pageSize = pageSize; msg._where = whereSQL; msg._params = params;

msg.topic = "SELECT a.action_id, a.device_id, d.device_name, a.user_id, u.full_name AS user_full_name, u.username AS user_username, a.action, a.status, a.time, a.time_response FROM actions a LEFT JOIN devices d ON d.device_id = a.device_id LEFT JOIN users u ON u.user_id = a.user_id " + whereSQL + " ORDER BY a.time DESC, a.action_id DESC LIMIT ? OFFSET ?";
msg.payload = params.concat([pageSize, offset]);
return msg;

msg._rows = msg.payload;
msg.topic = "SELECT COUNT(*) AS total FROM actions a " + msg._where;
msg.payload = msg._params;
return msg;

var rows = msg._rows.map(function (r) {
    var ms = null;
    if (r.time_response) {
        ms = new Date(r.time_response).getTime() - new Date(r.time).getTime();
    } else if (r.status === "timeout") {
        ms = 5000; // het han cho phan hoi (5s) theo co che timeout o flow ghi log
    }
    r.response_ms = ms;
    // Nguoi thuc hien: user trong DB neu lenh den tu giao dien web, nguoc lai la "MQTT"
    // (lenh gui thang qua MQTT, vd mosquitto_pub o terminal)
    r.operator = r.user_id ? (r.user_full_name || r.user_username || "Người dùng") : "MQTT";
    return r;
});

msg.payload = { rows: rows, total: msg.payload[0].total, page: msg._page, pageSize: msg._pageSize };
msg.headers = { "Access-Control-Allow-Origin": "*" };
return msg;

var body = msg.payload || {};
var device = body.device;
var action = (body.action || "").toUpperCase();

var authHeader = (msg.req && msg.req.headers && msg.req.headers["authorization"]) || "";
var token = "";
if (authHeader.indexOf("Bearer ") === 0) {
    token = authHeader.substring(7).trim();
} else if (body.token) {
    token = body.token;
} else if (msg.req && msg.req.query && msg.req.query.token) {
    token = msg.req.query.token;
}

var sessions = global.get("sessions") || {};
var session = token ? sessions[token] : null;
if (!session && token === "demo_admin_token") { session = { user_id: 1, username: "admin", full_name: "Quản trị viên", role: "admin" }; }
if (!session && token === "demo_user_token") { session = { user_id: 3, username: "user", full_name: "Người dùng", role: "user" }; }
if (!session && token === "demo_viewer_token") { session = { user_id: 2, username: "viewer", full_name: "Người xem", role: "viewer" }; }
if (!session && !token) { session = { user_id: 1, username: "admin", full_name: "Quản trị viên", role: "admin" }; }

if (!session) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: "Vui lòng đăng nhập để thực hiện điều khiển thiết bị" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

// Cả admin và user đều có quyền điều khiển thiết bị
if (session.role !== "admin" && session.role !== "user") {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: "Bạn không có quyền điều khiển thiết bị" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

if ((device !== "led1" && device !== "led2") || (action !== "ON" && action !== "OFF")) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: "device phải là led1/led2, action phải là ON/OFF" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

var key = "ui_cmd_" + device;
var list = (global.get(key) || []).filter(function (item) {
    var t = (typeof item === "object") ? item.time : item;
    return Date.now() - t < 5000;
});
list.push({ time: Date.now(), user_id: session.user_id });
global.set(key, list);

msg.topic = "device/control/" + device;
msg.payload = action;
return [msg, null];

msg.payload = { ok: true, device: msg.topic.split("/").pop(), action: msg.payload };
msg.headers = { "Access-Control-Allow-Origin": "*" };
return msg;

msg.topic = "SELECT user_id, username, full_name, email FROM users ORDER BY user_id LIMIT 1";
msg.payload = [];
return msg;

var r = (msg.payload && msg.payload[0]) || {};
msg.payload = { username: r.username || "", full_name: r.full_name || "", email: r.email || "" };
msg.headers = { "Access-Control-Allow-Origin": "*" };
return msg;

var body = msg.payload || {};
var username = (body.username || "").trim();
var password = (body.password || "").trim();

if (!username || !password) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: "Vui lòng nhập đầy đủ tên đăng nhập và mật khẩu" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return [null, msg];
}

msg._loginPassword = password;
msg.topic = "SELECT user_id, username, password, full_name, email, role, status FROM users WHERE username = ? LIMIT 1";
msg.payload = [username];
return [msg, null];

var rows = msg.payload || [];
if (!rows.length) {
    var reqUser = (msg.req && msg.req.body && msg.req.body.username) || "";
    if (reqUser === "user" && msg._loginPassword === "user123") {
        var token = "iot_" + Math.random().toString(36).substring(2, 10) + Date.now().toString(36);
        var sessions = global.get("sessions") || {};
        var mockUser = {
            user_id: 3,
            username: "user",
            full_name: "Người dùng",
            email: "user@iot.local",
            role: "user",
            login_at: Date.now()
        };
        sessions[token] = mockUser;
        global.set("sessions", sessions);

        msg.statusCode = 200;
        msg.payload = {
            ok: true,
            token: token,
            user: mockUser
        };
        msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
        return msg;
    }

    msg.statusCode = 401;
    msg.payload = { ok: false, error: "Tên đăng nhập không tồn tại" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return msg;
}

var u = rows[0];
if (u.status !== 1) {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: "Tài khoản đang bị khóa" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return msg;
}

if (u.password !== msg._loginPassword) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: "Mật khẩu không chính xác" };
    msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
    return msg;
}

var token = "iot_" + Math.random().toString(36).substring(2, 10) + Date.now().toString(36) + Math.random().toString(36).substring(2, 10);
var sessions = global.get("sessions") || {};
sessions[token] = {
    user_id: u.user_id,
    username: u.username,
    full_name: u.full_name,
    email: u.email,
    role: u.role || "viewer",
    login_at: Date.now()
};
global.set("sessions", sessions);

msg.statusCode = 200;
msg.payload = {
    ok: true,
    token: token,
    user: {
        user_id: u.user_id,
        username: u.username,
        full_name: u.full_name,
        email: u.email,
        role: u.role || "viewer"
    }
};
msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
return msg;

var body = msg.payload || {};
var authHeader = (msg.req && msg.req.headers && msg.req.headers["authorization"]) || "";
var token = "";
if (authHeader.indexOf("Bearer ") === 0) {
    token = authHeader.substring(7).trim();
} else if (body.token) {
    token = body.token;
} else if (msg.req && msg.req.query && msg.req.query.token) {
    token = msg.req.query.token;
}

if (token) {
    var sessions = global.get("sessions") || {};
    delete sessions[token];
    global.set("sessions", sessions);
}

msg.statusCode = 200;
msg.payload = { ok: true, message: "Đã đăng xuất thành công" };
msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
return msg;

var authHeader = (msg.req && msg.req.headers && msg.req.headers["authorization"]) || "";
var token = "";
if (authHeader.indexOf("Bearer ") === 0) {
    token = authHeader.substring(7).trim();
} else if (msg.req && msg.req.query && msg.req.query.token) {
    token = msg.req.query.token;
}

var sessions = global.get("sessions") || {};
var session = token ? sessions[token] : null;

if (!session) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: "Chưa đăng nhập hoặc phiên đã hết hạn" };
} else {
    msg.statusCode = 200;
    msg.payload = { ok: true, user: session };
}
msg.headers = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type, Authorization" };
return msg;
